package com.trampolim.api.career;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.HttpStatus;
@RestController @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanyCareerController {
 private final CompanyCareerService service;private final CompanySelectionService selection;private final RegionalObservatory observatory;
 public CompanyCareerController(CompanyCareerService service,CompanySelectionService selection,RegionalObservatory observatory){this.service=service;this.selection=selection;this.observatory=observatory;}
 @GetMapping("/api/company/challenges")public Map<String,Object> list(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){return service.challenges(email,before,limit);}
 @GetMapping("/api/company/challenges/{id}")public Map<String,Object> detail(@AuthenticationPrincipal String email,@PathVariable long id){return service.challenge(email,id);}
 @PostMapping("/api/company/challenges")public Map<String,Object> create(@AuthenticationPrincipal String email,@RequestBody CompanyCareerService.Challenge input){return service.save(email,0,input);}
 @PutMapping("/api/company/challenges/{id}")public Map<String,Object> edit(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody CompanyCareerService.Challenge input){return service.save(email,id,input);}
 @GetMapping("/api/company/challenges/{id}/submissions")public Map<String,Object> submissions(@AuthenticationPrincipal String email,@PathVariable long id,@RequestParam(required=false)UUID before,@RequestParam(defaultValue="20")int limit){return service.submissions(email,id,before,limit);}
 @PostMapping("/api/company/challenges/{id}/submissions/{receipt}/review")public Map<String,Object> review(@AuthenticationPrincipal String email,@PathVariable long id,@PathVariable UUID receipt,@RequestBody CompanyCareerService.Review input){return service.review(email,id,receipt,input);}
 @GetMapping("/api/company/listings/{id}/career-context")public Map<String,Object> context(@AuthenticationPrincipal String email,@PathVariable long id){return service.context(email,id);}
 @PutMapping("/api/company/listings/{id}/career-context")@ResponseStatus(HttpStatus.NO_CONTENT)public void context(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody CompanyCareerService.Context input){service.context(email,id,input);}
 @GetMapping("/api/company/career/applications")public List<Map<String,Object>> applications(@AuthenticationPrincipal String email){return selection.applications(email);}
 @PostMapping("/api/company/career/applications/{id}/outcome")public Map<String,Object> outcome(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody CompanySelectionService.Outcome input){return selection.record(email,id,input);}
 @GetMapping("/api/company/career/impact")public Map<String,Object> impact(@AuthenticationPrincipal String email){return selection.impact(email);}
 @GetMapping("/api/public/career/challenges")public Map<String,Object> challenges(@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String region){return service.publicChallenges(before,limit,region);}
 @GetMapping("/api/public/career/challenges/{id}")public Map<String,Object> challenge(@PathVariable long id){return service.publicChallenge(id);}
 @GetMapping("/api/public/career/opportunities")public Map<String,Object> opportunities(@RequestParam(defaultValue="")String regime,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="false")boolean first,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){return service.opportunities(regime,region,first,before,limit);}
 @GetMapping("/api/public/career/observatory")public Map<String,Object> observatory(@RequestParam(defaultValue="")String region,@RequestParam String from,@RequestParam String to,jakarta.servlet.http.HttpServletRequest request){return observatory.dashboard(region,from,to,request.getRemoteAddr());}
 @PostMapping("/api/integrations/career/challenges/submit")public Map<String,Object> receive(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CompanyCareerService.Delivery input){return service.receive(key,input);}
 @PostMapping("/api/integrations/career/challenges/receipt")public Map<String,Object> receipt(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CompanyCareerService.Receipt input){return service.receipt(key,input);}
 @PostMapping("/api/integrations/career/challenges/withdraw")public Map<String,Object> withdraw(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CompanyCareerService.Receipt input){return service.withdraw(key,input);}
 @PostMapping("/api/integrations/career/outcomes/preview")public Map<String,Object> preview(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CompanySelectionService.Confirmation input){return selection.preview(key,input);}
 @PostMapping("/api/integrations/career/outcomes/confirm")public Map<String,Object> confirm(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CompanySelectionService.Confirmation input){return selection.confirm(key,input);}
}
